<?php
$reportPath=\App\Security\CspReports::PATH;
$headers=['Content-Type: application/csp-report','Origin: '.$fixtureOrigin,'Sec-Fetch-Site: same-origin'];
$body=['csp-report'=>['document-uri'=>$fixtureOrigin.'/login/reset?token=CSP_PRIVATE_MARKER','disposition'=>'report','effective-directive'=>'script-src-elem','blocked-uri'=>'inline','source-file'=>'CSP_PRIVATE_MARKER','script-sample'=>'CSP_PRIVATE_MARKER','referrer'=>'https://private.example/CSP_PRIVATE_MARKER']];
$json=json_encode($body,JSON_THROW_ON_ERROR);
$home=installRequest('/');
checkInstall(!str_contains($home['headers'],'Content-Security-Policy-Report-Only:'),'La observación está activa sin habilitarla.');
checkInstall(installRequest($reportPath,$json,$headers)['status']===204 && (int)$db->query('SELECT COUNT(*) FROM goldensite_csp_reports')->fetchColumn()===0,'Se guardaron informes estando desactivada.');
checkInstall(installRequest('/login',['csrf_token'=>installCsrf(installRequest('/login')),'email'=>'owner@example.test','password'=>$password])['status']===302,'No se pudo acceder a las pruebas CSP.');
$panel=installRequest('/admin/waf'); $csrf=installCsrf($panel);
checkInstall($panel['status']===200 && str_contains($panel['body'],'gs-csp-observation'),'Falta observación CSP en el WAF.');
checkInstall(installRequest('/admin/waf',['action'=>'save_csp_observation','csp_observe'=>'1','current_password'=>$password])['status']===403,'La activación permite omitir CSRF.');
checkInstall(installRequest('/admin/waf',['csrf_token'=>$csrf,'action'=>'save_csp_observation','csp_observe'=>'1','current_password'=>'wrong'])['status']===422,'Se activó sin contraseña correcta.');
checkInstall(installRequest('/admin/waf',['csrf_token'=>$csrf,'action'=>'save_csp_observation','csp_observe'=>'1','current_password'=>$password])['status']===302,'No se pudo activar observación CSP.');
$home=installRequest('/');
checkInstall(str_contains($home['headers'],"Content-Security-Policy-Report-Only: script-src 'self'") && str_contains($home['headers'],'report-to goldensite-csp') && str_contains($home['headers'],'Reporting-Endpoints: goldensite-csp="'.$fixtureOrigin.$reportPath.'"'),'Las cabeceras de observación no apuntan al propio sitio.');
checkInstall(str_contains($home['headers'],"Content-Security-Policy: script-src 'self' https: 'unsafe-inline'; object-src 'none'; base-uri 'self'; frame-ancestors 'self'"),'Cambió la CSP aplicada al sitio.');
checkInstall(!str_contains($home['headers'],'report-sample'),'La política solicita muestras de código.');
// Reports must work without a logged-in session or an administrative CSRF token.
$adminCookie=$cookie; $cookie=$fixture.'/storage/csp-anonymous.cookie';
checkInstall(installRequest($reportPath,$json,$headers)['status']===204,'No se recibió un informe anónimo válido.');
$row=$db->query('SELECT * FROM goldensite_csp_reports')->fetch();
checkInstall($row['area']==='account' && $row['directive']==='script-src-elem' && $row['blocked_kind']==='inline' && (int)$row['events']===1,'El informe no se normalizó.');
checkInstall(!str_contains(json_encode($row),'CSP_PRIVATE_MARKER') && !str_contains(json_encode($row),'127.0.0.1') && count($row)===6,'Se guardaron datos privados del informe.');
$modern=[['type'=>'csp-violation','body'=>['documentURL'=>$fixtureOrigin.'/admin/dashboard?token=CSP_PRIVATE_MARKER','disposition'=>'report','effectiveDirective'=>'script-src-elem','blockedURL'=>'https://private.example/CSP_PRIVATE_MARKER','sample'=>'CSP_PRIVATE_MARKER']]];
$modern[]=$modern[0];
checkInstall(installRequest($reportPath,json_encode($modern),['Content-Type: application/reports+json','Origin: '.$fixtureOrigin])['status']===204,'No se recibió el formato moderno.');
checkInstall((int)$db->query("SELECT events FROM goldensite_csp_reports WHERE area='admin' AND blocked_kind='external'")->fetchColumn()===2,'El lote moderno no se agregó correctamente.');
checkInstall(installRequest($reportPath,$json,['Content-Type: application/csp-report','Origin: https://outside.example'])['status']===403,'Se aceptó Origin de otro sitio.');
checkInstall(installRequest($reportPath,$json,['Content-Type: application/csp-report','Sec-Fetch-Site: cross-site'])['status']===403,'Se aceptó una petición cross-site.');
$foreign=$body; $foreign['csp-report']['document-uri']='https://outside.example/';
checkInstall(installRequest($reportPath,json_encode($foreign),$headers)['status']===400,'Se aceptó un documento de otro origen.');
checkInstall(installRequest($reportPath,'{invalid',$headers)['status']===400,'Se aceptó JSON inválido.');
checkInstall(installRequest($reportPath,$json,['Content-Type: application/json'])['status']===415,'Se aceptó un formato de contenido no previsto.');
checkInstall(installRequest($reportPath,str_repeat('x',16385),$headers)['status']===413,'No se limita el tamaño de recepción.');
checkInstall(installRequest($reportPath,json_encode(array_fill(0,9,$modern[0])),['Content-Type: application/reports+json'])['status']===400,'No se limita el lote de informes.');
$enforce=$body;$enforce['csp-report']['disposition']='enforce';
checkInstall(installRequest($reportPath,json_encode($enforce),$headers)['status']===400,'Se mezclan informes de observación y de bloqueo.');
checkInstall(installRequest($reportPath.'/other',$json,$headers)['status']===403,'La excepción CSRF permite rutas vecinas.');
checkInstall(installRequest($reportPath)['status']===404,'El receptor permite GET.');
$db->exec("INSERT INTO goldensite_csp_reports VALUES (DATE_SUB(UTC_DATE(),INTERVAL 14 DAY),'public','script-src','inline',1,UTC_TIMESTAMP())");
checkInstall(installRequest($reportPath,$json,$headers)['status']===204 && (int)$db->query('SELECT COUNT(*) FROM goldensite_csp_reports WHERE report_day<DATE_SUB(UTC_DATE(),INTERVAL 13 DAY)')->fetchColumn()===0,'No se purgan los informes vencidos.');
$rateFile=$fixture.'/storage/rate-limits/'.hash('sha256',$environment['RATE_LIMIT_NAMESPACE'].'|csp-reports:ip:127.0.0.1').'.json';
file_put_contents($rateFile,json_encode(['expires'=>time()+60,'count'=>20]));
$before=(int)$db->query('SELECT SUM(events) FROM goldensite_csp_reports')->fetchColumn();
checkInstall(installRequest($reportPath,$json,$headers)['status']===429 && (int)$db->query('SELECT SUM(events) FROM goldensite_csp_reports')->fetchColumn()===$before,'No se limita la recepción por dirección.');
file_put_contents($rateFile,json_encode(['expires'=>time()+60,'count'=>0]));
$globalRateFile=$fixture.'/storage/rate-limits/'.hash('sha256',$environment['RATE_LIMIT_NAMESPACE'].'|csp-reports:site').'.json';
file_put_contents($globalRateFile,json_encode(['expires'=>time()+60,'count'=>60]));
checkInstall(installRequest($reportPath,$json,$headers)['status']===429 && (int)$db->query('SELECT SUM(events) FROM goldensite_csp_reports')->fetchColumn()===$before,'No se limita la recepción global.');
checkInstall((int)$db->query('SELECT COUNT(*) FROM goldensite_waf_blacklist')->fetchColumn()===0,'Los avisos CSP generaron bloqueos de IP.');
$cookie=$adminCookie;
$panel=installRequest('/admin/waf');
checkInstall(str_contains(html_entity_decode($panel['body'],ENT_QUOTES|ENT_HTML5,'UTF-8'),'Acceso y cuenta') && !str_contains($panel['body'],'CSP_PRIVATE_MARKER'),'El panel no presenta el resumen privado esperado.');
checkInstall(installRequest('/admin/waf',['csrf_token'=>$csrf,'action'=>'save_csp_observation','current_password'=>$password])['status']===302,'No se pudo desactivar la observación.');
checkInstall(!str_contains(installRequest('/')['headers'],'Content-Security-Policy-Report-Only:'),'La desactivación conserva la cabecera de observación.');
checkInstall(installRequest($reportPath,$json,$headers)['status']===204 && (int)$db->query('SELECT SUM(events) FROM goldensite_csp_reports')->fetchColumn()===$before,'La desactivación sigue registrando avisos.');
$db->prepare('INSERT INTO goldensite_access_roles (name,permissions_json) VALUES (?,?)')->execute(['CSP fixture role','["dashboard.read","security.read","security.write"]']);
$roleId=(int)$db->lastInsertId();
$db->prepare("INSERT INTO users (username,email,password,role,role_id,status) VALUES (?,?,?,'user',2,'active')")->execute(['csp_fixture','csp@example.test',password_hash($password,PASSWORD_DEFAULT)]);
$limitedId=(int)$db->lastInsertId();
$db->prepare('INSERT INTO goldensite_access_members (user_id,role_id) VALUES (?,?)')->execute([$limitedId,$roleId]);
try {
    installRequest('/logout',['csrf_token'=>$csrf]);
    checkInstall(installRequest('/login',['csrf_token'=>installCsrf(installRequest('/login')),'email'=>'csp@example.test','password'=>$password])['status']===302,'No se pudo iniciar la sesión delegada.');
    $delegated=installRequest('/admin/waf');
    checkInstall($delegated['status']===200 && !str_contains($delegated['body'],'value="save_csp_observation"'),'La cuenta delegada recibe el control reservado.');
    checkInstall(installRequest('/admin/waf',['csrf_token'=>installCsrf($delegated),'action'=>'save_csp_observation','csp_observe'=>'1','current_password'=>$password])['status']===403,'Una cuenta delegada puede activar la observación.');
} finally {
    $db->prepare('DELETE FROM goldensite_access_members WHERE user_id=?')->execute([$limitedId]);
    $db->prepare('DELETE FROM goldensite_access_roles WHERE id=?')->execute([$roleId]);
    $db->prepare('DELETE FROM users WHERE id=?')->execute([$limitedId]);
}
echo "OK: $checks comprobaciones de instalación, actualización y observación CSP.\n";
